css:
* { margin: 0; padding: 0; box-sizing: border-box; }

body {
  width: 100%; height: 100%;
  background: transparent;
  font-family: -apple-system, "PingFang SC", "Hiragino Sans", sans-serif;
}

/* 整体容器：完全透明 */
.widget {
  width: 100%; height: 100%;
  background: transparent;
  padding: 4px;
  display: flex;
  flex-direction: column;
  gap: 6px;
}

/* ── 气泡 + 箭头的外层包裹 ── */
.bubble-wrap {
  flex: 1;
  min-height: 0;
  display: flex;
  flex-direction: column;
  align-items: center; /* 箭头水平居中 = 对准 Home */
}

/* 半透明白色气泡框，磨砂玻璃效果 */
.bubble {
  width: 100%;
  flex: 1;
  min-height: 0;
  background: rgba(255, 255, 255, 0.78);
  backdrop-filter: blur(14px);
  -webkit-backdrop-filter: blur(14px);
  border-radius: 18px;
  padding: 6px;
  display: flex;
  flex-direction: column;
  gap: 5px;
}

/* 三角形箭头
   ▸ 颜色与气泡完全一致
   ▸ margin-top: -1px 向上咬入气泡 1px，消除抗锯齿缝隙，无缝连接 */
.arrow {
  flex-shrink: 0;
  margin-top: -1px;
  width: 0;
  height: 0;
  border-left:  12px solid transparent;
  border-right: 12px solid transparent;
  border-top:   12px solid rgba(255, 255, 255, 0.78);
}

/* ── 白色联系人卡片 ── */
.card {
  flex: 1;
  min-height: 0;
  background: rgba(255, 255, 255, 0.92);
  border-radius: 12px;
  padding: 0 8px;
  display: flex;
  align-items: center;
  gap: 8px;
  overflow: hidden;
}

.avatar {
  width: 42px;
  height: 42px;
  border-radius: 10px;
  background: #ddd8d0 center/cover no-repeat;
  flex-shrink: 0;
}

.info {
  flex: 1;
  min-width: 0;
  display: flex;
  flex-direction: column;
  gap: 2px;
}

.top-row {
  display: flex;
  align-items: center;
  justify-content: space-between;
}

.status       { font-size: 9px; color: #8e8e93; }
.badge        { font-size: 9px; color: #8e8e93; }
.badge b      { font-weight: 700; color: #1c1c1e; }

.name {
  font-size: 12px;
  font-weight: 700;
  color: #1c1c1e;
  white-space: nowrap;
  overflow: hidden;
  text-overflow: ellipsis;
  line-height: 1.3;
}

.sub {
  font-size: 9px;
  color: #b0b0b5;
  white-space: nowrap;
  overflow: hidden;
  text-overflow: ellipsis;
}

/* ── 底部导航栏，同款半透明白 ── */
.navbar {
  height: 38px;
  flex-shrink: 0;
  background: rgba(255, 255, 255, 0.78);
  backdrop-filter: blur(14px);
  -webkit-backdrop-filter: blur(14px);
  border-radius: 14px;
  display: flex;
  align-items: center;
  justify-content: space-around;
  padding-bottom: 2px;
}

.nav-item {
  flex: 1;
  display: flex;
  flex-direction: column;
  align-items: center;
  justify-content: center;
  gap: 2px;
  color: #a0a0a8;
}

.nav-item.active { color: #2c2c2e; }

.icon { width: 14px; height: 14px; }

.nav-item span {
  font-size: 5.5px;
  color: inherit;
  line-height: 1;
}
